342		// both variants make the same wrong selection.
343		wantSources := []SourceTrace{
344			{Root: "R1", Path: []string{"T", "A", "Z", "M", "R1"}},
345			{Root: "R2", Path: []string{"T", "A", "Z", "M", "R2"}},
346		}
347		if !reflect.DeepEqual(want.Sources, wantSources) {
348			t.Errorf("Sources = %+v, want %+v", want.Sources, wantSources)
349		}
350		if want.ContentID == "" || want.Dataset != "T" {
