1	package chainledger
2	
3	import (
4		"encoding/json"
5		"reflect"
6		"strings"
7		"testing"
8	)
9	
10	// This file pins down the independence between the three things a batch
11	// caller can hold at once:
12	//
13	//   - the submitted Plan (which the caller may keep editing for display or
14	//     reuse after PreviewBatch/ApplyBatch has returned);
15	//   - the current in-memory graph (which later batches keep adjusting);
16	//   - the already returned *BatchReport values (which describe the graph as it
17	//     was when that call returned, never anything that happened afterwards).
18	//
19	// Every scenario is built around replacing one existing dataset's direct
20	// upstreams: the graph contains the old upstream, the new upstream(s), and a
21	// downstream that keeps depending on the adjusted dataset. The focus is the
22	// direct-upstream list of every dataset in the report's final graph.
23	
24	// independenceGraph builds: roots A, D, E; B depends on A; C depends on B.
25	func independenceGraph(t *testing.T) map[string]*Lineage {
26		t.Helper()
27		return buildGraph(t, P("A"), P("D"), P("E"), P("B", "A"), P("C", "B"))
28	}
29	
30	// replacementPlan is deliberately out of order and duplicated
31	// (E, D, D, E): the result must normalize to [D E], while the submitted plan
32	// keeps exactly these bytes.
33	func replacementPlan() Plan {
34		return planOf(change("B", "E", "D", "D", "E"))
35	}
36	
37	// clonePlan returns a deep copy of p so a test can compare the whole plan
38	// value after the caller mutates every slice it owns.
39	func clonePlan(p Plan) Plan {
40		c := Plan{
41			Changes:  make([]PlanChange, len(p.Changes)),
42			Removals: append([]string(nil), p.Removals...),
43		}
44		for i, ch := range p.Changes {
45			c.Changes[i] = PlanChange{
46				Name:      ch.Name,
47				Upstreams: append([]string(nil), ch.Upstreams...),
48			}
49		}
50		return c
51	}
