83	// TestBatchPreviewKeepsCurrentGraphAndDescribesReplacement pins the preview
84	// contract: a successful preview leaves every current-graph relationship
85	// exactly where it was, while the returned report describes the post-replace
86	// graph (new upstreams adopted, downstream kept).
87	func TestBatchPreviewKeepsCurrentGraphAndDescribesReplacement(t *testing.T) {
88		graph := independenceGraph(t)
89		plan := replacementPlan()
90		before := dump(graph)
91	
92		report, err := PreviewBatch(graph, plan)
93		if err != nil {
94			t.Fatalf("PreviewBatch unexpected error: %v", err)
95		}
96	
97		// The current graph is untouched: B still points at the old upstream A and
98		// nothing has been linked to D or E.
99		if got := dump(graph); got != before {
100			t.Fatalf("preview mutated the current graph:\n got %s\nwant %s", got, before)
101		}
102		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"A"}) {
103			t.Errorf("B.Parents = %v, want [A] (preview must not replace upstreams)", got)
104		}
105		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
106			t.Errorf("B.Children = %v, want [C]", got)
107		}
108		if got := graph["A"].Children; !reflect.DeepEqual(got, []string{"B"}) {
109			t.Errorf("A.Children = %v, want [B] (old edge still present after preview)", got)
110		}
111		if got := graph["D"].Children; len(got) != 0 {
112			t.Errorf("D.Children = %v, want empty (preview must not create edges)", got)
113		}
114		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
115			t.Errorf("C.Parents = %v, want [B]", got)
116		}
117	
118		// The report describes the replaced graph: B normalized to [D E], the old
119		// upstream A is now a root, and the downstream C is untouched.
120		if got := mustReportDataset(t, report, "B").Upstreams; !reflect.DeepEqual(got, []string{"D", "E"}) {
121			t.Errorf("report B.upstreams = %v, want [D E]", got)
122		}
123		if got := mustReportDataset(t, report, "A").Upstreams; !reflect.DeepEqual(got, []string{}) {
124			t.Errorf("report A.upstreams = %v, want [] (old upstream stays in graph as a root)", got)
125		}
126		if got := mustReportDataset(t, report, "C").Upstreams; !reflect.DeepEqual(got, []string{"B"}) {
127			t.Errorf("report C.upstreams = %v, want [B] (downstream relationship kept)", got)
128		}
129		if got := mustReportDataset(t, report, "D").Upstreams; !reflect.DeepEqual(got, []string{}) {
130			t.Errorf("report D.upstreams = %v, want []", got)
131		}
132		if !reflect.DeepEqual(report.ChangedDatasets, []string{"B"}) {
133			t.Errorf("ChangedDatasets = %v, want [B]", report.ChangedDatasets)
134		}
135		wantAdded := []Relation{{Upstream: "D", Downstream: "B"}, {Upstream: "E", Downstream: "B"}}
136		if !reflect.DeepEqual(report.AddedRelations, wantAdded) {
137			t.Errorf("AddedRelations = %v, want %v", report.AddedRelations, wantAdded)
138		}
139		wantRemoved := []Relation{{Upstream: "A", Downstream: "B"}}
140		if !reflect.DeepEqual(report.RemovedRelations, wantRemoved) {
141			t.Errorf("RemovedRelations = %v, want %v", report.RemovedRelations, wantRemoved)
142		}
143		if !reflect.DeepEqual(report.AffectedDownstreams, []string{"C"}) {
144			t.Errorf("AffectedDownstreams = %v, want [C]", report.AffectedDownstreams)
145		}
146	}
