148	// TestBatchApplyAdoptsUpstreamsAndPreservesDownstream pins the apply contract:
149	// the current graph adopts the new direct upstreams (sorted, deduplicated, and
150	// copied off the caller's slices), the downstream relationship survives, and
151	// the returned report matches that application.
152	func TestBatchApplyAdoptsUpstreamsAndPreservesDownstream(t *testing.T) {
153		graph := independenceGraph(t)
154		plan := replacementPlan()
155	
156		applied, err := ApplyBatch(graph, plan)
157		if err != nil {
158			t.Fatalf("ApplyBatch unexpected error: %v", err)
159		}
160	
161		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"D", "E"}) {
162			t.Errorf("B.Parents = %v, want [D E]", got)
163		}
164		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
165			t.Errorf("B.Children = %v, want [C] (downstream must survive the replacement)", got)
166		}
167		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"B"}) {
168			t.Errorf("C.Parents = %v, want [B]", got)
169		}
170		if got := graph["A"].Children; len(got) != 0 {
171			t.Errorf("A.Children = %v, want empty (old edge dissolved)", got)
172		}
173		if got := graph["D"].Children; !reflect.DeepEqual(got, []string{"B"}) {
174			t.Errorf("D.Children = %v, want [B]", got)
175		}
176		if got := graph["E"].Children; !reflect.DeepEqual(got, []string{"B"}) {
177			t.Errorf("E.Children = %v, want [B]", got)
178		}
179		if roots := Roots(graph); !reflect.DeepEqual(roots, []string{"A", "D", "E"}) {
180			t.Errorf("Roots = %v, want [A D E]", roots)
181		}
182	
183		// The report returned by apply matches a preview against the same
184		// pre-application inputs.
185		preview, err := PreviewBatch(independenceGraph(t), replacementPlan())
186		if err != nil {
187			t.Fatalf("PreviewBatch unexpected error: %v", err)
188		}
189		if !reflect.DeepEqual(applied, preview) {
190			t.Errorf("apply report differs from preview:\n apply=%#v\n preview=%#v", applied, preview)
191		}
192		if got := mustReportDataset(t, applied, "B").Upstreams; !reflect.DeepEqual(got, []string{"D", "E"}) {
193			t.Errorf("applied report B.upstreams = %v, want [D E]", got)
194		}
195		if got := mustReportDataset(t, applied, "C").Upstreams; !reflect.DeepEqual(got, []string{"B"}) {
196			t.Errorf("applied report C.upstreams = %v, want [B]", got)
197		}
198	
199		// The applied graph keeps no backing memory from the submitted plan:
200		// rewriting and appending to the plan's slices must not move the graph.
201		plan.Changes[0].Upstreams[0] = "A"
202		plan.Changes[0].Upstreams = append(plan.Changes[0].Upstreams, "ghost")
203		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"D", "E"}) {
204			t.Fatalf("editing the submitted plan altered applied graph B.Parents: %v", got)
205		}
206		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
207			t.Fatalf("editing the submitted plan altered applied graph B.Children: %v", got)
208		}
209	
210		// The applied report keeps a frozen copy: in-place edits of the graph's
211		// stored parents after apply must not move the returned report.
212		graph["B"].Parents[0] = "HACK"
213		graph["B"].Parents = append(graph["B"].Parents, "ghost")
214		if got := mustReportDataset(t, applied, "B").Upstreams; !reflect.DeepEqual(got, []string{"D", "E"}) {
215			t.Fatalf("applied report followed a later graph edit: got %v, want frozen [D E]", got)
216		}
217		graph["B"].Parents = []string{"D", "E"}
218	
219		// The reverse direction on a fresh preview: editing a returned report for
220		// display never reaches the graph it was computed from.
221		displayGraph := independenceGraph(t)
222		displayReport, err := PreviewBatch(displayGraph, replacementPlan())
223		if err != nil {
224			t.Fatalf("display PreviewBatch unexpected error: %v", err)
225		}
226		iDisplay := datasetIndex(displayReport, "B")
227		displayReport.FinalGraph.Datasets[iDisplay].Upstreams[0] = "HACK"
228		displayReport.FinalGraph.Datasets[iDisplay].Upstreams = append(displayReport.FinalGraph.Datasets[iDisplay].Upstreams, "ghost")
229		if got := displayGraph["B"].Parents; !reflect.DeepEqual(got, []string{"A"}) {
230			t.Fatalf("editing a preview report altered graph B.Parents: %v", got)
231		}
232		if got := displayGraph["D"].Children; len(got) != 0 {
233			t.Fatalf("editing a preview report created edges: D.Children = %v", got)
234		}
235	}
