3	import (
4		"encoding/json"
5		"errors"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// Regression coverage for a batch that deletes a SHARED intermediate dataset
12	// while the retained downstream is rewired onto surviving upstreams within the
13	// same plan.
14	//
15	// The fixture keeps two converging branches:
16	//
17	//	R -> M -> B -> H -> T
18	//	     \-> C -/     (H also depends on C, so the branches meet at H)
19	//	S -> (root, initially unrelated)
20	//	U -> V            (an isolated component that must never be touched)
21	//
22	// The batch deletes M and B, repoints C wholesale at R, and repoints H
23	// wholesale at C and S:
24	//
25	//	R -> C -> H -> T
26	//	S ----/
27	//
28	// It must succeed: H and T are retained even though both of H's old upstreams
29	// (B, and the path through M) disappear, because the plan reconnects H inside
30	// the same batch. These tests pin the report's three-way classification
31	// (deleted / directly adjusted / indirectly affected), guard the deleted-edge
32	// list against missing relations and the affected list against double-counting
33	// the converging downstream, and guard the atomicity of a rejected batch.
34	
35	// convergenceBatchGraph builds R,S roots; M depends on R; B and C both depend
36	// on M; H depends on B and C; T depends on H; plus the isolated U -> V pair.
37	func convergenceBatchGraph(t *testing.T) map[string]*Lineage {
38		t.Helper()
39		return buildGraph(t,
40			P("R"),
41			P("S"),
42			P("M", "R"),
43			P("B", "M"),
44			P("C", "M"),
45			P("H", "B", "C"),
46			P("T", "H"),
47			P("U"),
48			P("V", "U"),
49		)
50	}
51	
52	// convergenceBatchPlan is the successful plan: remove M and B, repoint C at R,
53	// repoint H at C and S.
54	func convergenceBatchPlan() Plan {
55		return Plan{
56			Changes: []PlanChange{
57				change("C", "R"),
58				change("H", "C", "S"),
59			},
60			Removals: []string{"M", "B"},
61		}
62	}
63	
64	// wantConvergenceFinal is the exact expected final graph, sorted by name with
65	// sorted upstream lists.
66	var wantConvergenceFinal = []GraphDataset{
67		{Name: "C", Upstreams: []string{"R"}},
68		{Name: "H", Upstreams: []string{"C", "S"}},
69		{Name: "R", Upstreams: []string{}},
70		{Name: "S", Upstreams: []string{}},
71		{Name: "T", Upstreams: []string{"H"}},
72		{Name: "U", Upstreams: []string{}},
73		{Name: "V", Upstreams: []string{"U"}},
74	}
75	
76	// TestBatchDeleteSharedIntermediateSucceeds is the headline scenario: the
77	// shared intermediate M and one converging branch B are deleted, while the
78	// retained downstream H is rewired onto C and S inside the same batch. H and T
79	// survive; the isolated U/V component is untouched.
80	func TestBatchDeleteSharedIntermediateSucceeds(t *testing.T) {
81		graph := convergenceBatchGraph(t)
82		plan := convergenceBatchPlan()
83	
84		report, err := PreviewBatch(graph, plan)
85		if err != nil {
86			t.Fatalf("PreviewBatch unexpected error: %v", err)
87		}
88	
89		// Deleted datasets are exactly M and B.
90		if got, want := report.RemovedDatasets, []string{"B", "M"}; !reflect.DeepEqual(got, want) {
91			t.Errorf("RemovedDatasets = %v, want %v", got, want)
92		}
93		// Directly adjusted datasets are exactly C and H; T must not join them.
94		if got, want := report.ChangedDatasets, []string{"C", "H"}; !reflect.DeepEqual(got, want) {
95			t.Errorf("ChangedDatasets = %v, want %v", got, want)
96		}
97		// The plan registers no dataset.
98		if got := report.NewDatasets; !reflect.DeepEqual(got, []string{}) {
99			t.Errorf("NewDatasets = %v, want []", got)
100		}
101		// T is the sole indirectly affected downstream, once; H (directly
102		// adjusted) and every root must be absent from this list.
103		if got, want := report.AffectedDownstreams, []string{"T"}; !reflect.DeepEqual(got, want) {
104			t.Errorf("AffectedDownstreams = %v, want %v (converging T counted once, adjusted H excluded)", got, want)
105		}
106	
107		// Direct relations removed together with the deleted nodes and repoints:
108		// R->M, M->B, M->C, B->H. The edge C->H survives and must not appear here.
109		if got, want := report.RemovedRelations, []Relation{
110			{Upstream: "B", Downstream: "H"},
111			{Upstream: "M", Downstream: "B"},
112			{Upstream: "M", Downstream: "C"},
113			{Upstream: "R", Downstream: "M"},
114		}; !reflect.DeepEqual(got, want) {
115			t.Errorf("RemovedRelations = %v, want %v", got, want)
116		}
117		// Only genuinely new direct edges are R->C and S->H. Reachable paths that
118		// merely still exist (C->H, H->T) must not be invented as added edges.
119		if got, want := report.AddedRelations, []Relation{
120			{Upstream: "R", Downstream: "C"},
121			{Upstream: "S", Downstream: "H"},
122		}; !reflect.DeepEqual(got, want) {
123			t.Errorf("AddedRelations = %v, want %v", got, want)
124		}
125	
126		// The final graph is exactly the rewired one: M and B gone, no retained
127		// dataset references them, U/V and their edge untouched.
128		if got := report.FinalGraph.Datasets; !reflect.DeepEqual(got, wantConvergenceFinal) {
129			t.Errorf("FinalGraph.Datasets = %v, want %v", got, wantConvergenceFinal)
130		}
131		for _, ds := range report.FinalGraph.Datasets {
132			for _, upstream := range ds.Upstreams {
133				if upstream == "M" || upstream == "B" {
134					t.Errorf("final dataset %q still references deleted upstream %q", ds.Name, upstream)
135				}
136			}
137		}
138	}
139	
140	// TestBatchDeleteSharedIntermediatePreviewIsReadOnly: preview reports the
141	// result but leaves every node and bidirectional (parent/child) record of the
142	// original graph exactly as submitted.
143	func TestBatchDeleteSharedIntermediatePreviewIsReadOnly(t *testing.T) {
144		graph := convergenceBatchGraph(t)
145		before := dump(graph)
146	
147		if _, err := PreviewBatch(graph, convergenceBatchPlan()); err != nil {
148			t.Fatalf("PreviewBatch unexpected error: %v", err)
149		}
150		if got := dump(graph); got != before {
151			t.Fatalf("preview mutated the graph:\n got %s\nwant %s", got, before)
152		}
153		// Pin the bidirectional state explicitly: M and B are still present, and
154		// the children derived from the original edges are intact.
155		for name, parents := range map[string][]string{
156			"M": {"R"}, "B": {"M"}, "C": {"M"}, "H": {"B", "C"}, "T": {"H"}, "V": {"U"},
157		} {
158			if got := graph[name].Parents; !reflect.DeepEqual(got, parents) {
159				t.Errorf("after preview %s.Parents = %v, want %v", name, got, parents)
160			}
161		}
162		if got := graph["M"].Children; !reflect.DeepEqual(got, []string{"B", "C"}) {
163			t.Errorf("after preview M.Children = %v, want [B C]", got)
164		}
165		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"H"}) {
166			t.Errorf("after preview B.Children = %v, want [H]", got)
167		}
168	}
169	
170	// TestBatchDeleteSharedIntermediateApplyMatchesPreview: apply commits exactly
171	// the final graph the preview reported, with an identical report; parents and
172	// the derived children are both rebuilt.
173	func TestBatchDeleteSharedIntermediateApplyMatchesPreview(t *testing.T) {
174		graph := convergenceBatchGraph(t)
175	
176		preview, err := PreviewBatch(graph, convergenceBatchPlan())
177		if err != nil {
178			t.Fatalf("PreviewBatch unexpected error: %v", err)
179		}
180		applied, err := ApplyBatch(graph, convergenceBatchPlan())
181		if err != nil {
182			t.Fatalf("ApplyBatch unexpected error: %v", err)
183		}
184		if !reflect.DeepEqual(preview, applied) {
185			t.Fatalf("preview and apply reports differ:\n preview=%#v\n applied=%#v", preview, applied)
186		}
187	
188		// M and B are gone, with no dangling references.
189		if _, ok := graph["M"]; ok {
190			t.Errorf("M still in graph after apply")
191		}
192		if _, ok := graph["B"]; ok {
193			t.Errorf("B still in graph after apply")
194		}
195		for name, entry := range graph {
196			for _, parent := range entry.Parents {
197				if parent == "M" || parent == "B" {
198					t.Errorf("applied dataset %q still references deleted %q", name, parent)
199				}
200			}
201		}
202		// Parents of the retained nodes match the reported final graph, and the
203		// derived children were rebuilt from the rewired edges.
204		wantParents := map[string][]string{
205			"R": nil, "S": nil, "C": {"R"}, "H": {"C", "S"}, "T": {"H"}, "U": nil, "V": {"U"},
206		}
207		for name, parents := range wantParents {
208			if got := graph[name].Parents; !reflect.DeepEqual(got, parents) {
209				t.Errorf("after apply %s.Parents = %v, want %v", name, got, parents)
210			}
211		}
212		for name, children := range map[string][]string{
213			"R": {"C"}, "S": {"H"}, "C": {"H"}, "H": {"T"}, "T": nil, "U": {"V"}, "V": nil,
214		} {
215			if got := graph[name].Children; !reflect.DeepEqual(got, children) {
216				t.Errorf("after apply %s.Children = %v, want %v", name, got, children)
217			}
218		}
219	
220		// The applied graph exports exactly the final graph carried in the report.
221		exported, err := MarshalGraphFile(graph)
222		if err != nil {
223			t.Fatalf("MarshalGraphFile unexpected error: %v", err)
224		}
225		finalBytes, err := json.MarshalIndent(preview.FinalGraph, "", "  ")
226		if err != nil {
227			t.Fatalf("marshal reported final graph: %v", err)
228		}
229		if string(exported) != string(finalBytes) {
230			t.Fatalf("applied graph differs from the preview final graph:\n applied:\n%s\n preview:\n%s", exported, finalBytes)
231		}
232		// The exported graph must round-trip through the file reader unchanged.
233		parsed, err := UnmarshalGraphFile(exported)
234		if err != nil {
235			t.Fatalf("UnmarshalGraphFile on applied graph: %v", err)
236		}
237		if !reflect.DeepEqual(parsed, graph) {
238			t.Fatalf("applied graph does not round-trip:\n parsed %#v\n graph  %#v", parsed, graph)
239		}
240	}
241	
242	// TestBatchDeleteSharedIntermediateRejectsMissingDownstreamAdjustment is the
243	// refusal counterpart: the plan still deletes M and B and repoints C, but
244	// forgets to repoint H. H keeps a direct reference to deleted B, so both
245	// preview and apply must reject the whole batch, naming H (the referrer) and B
246	// (the referenced name), and no success report may be produced.
247	func TestBatchDeleteSharedIntermediateRejectsMissingDownstreamAdjustment(t *testing.T) {
248		plan := Plan{
249			Changes:  []PlanChange{change("C", "R")},
250			Removals: []string{"M", "B"},
251		}
252	
253		for _, mode := range []string{"preview", "apply"} {
254			t.Run(mode, func(t *testing.T) {
255				graph := convergenceBatchGraph(t)
256				before := dump(graph)
257	
258				var report *BatchReport
259				var err error
260				if mode == "preview" {
261					report, err = PreviewBatch(graph, plan)
262				} else {
263					report, err = ApplyBatch(graph, plan)
264				}
265				if err == nil {
266					t.Fatalf("%s succeeded on a dangling reference, report = %+v", mode, report)
267				}
268				if !errors.Is(err, ErrNotFound) {
269					t.Errorf("err = %v, want ErrNotFound", err)
270				}
271				if !strings.Contains(err.Error(), "H") || !strings.Contains(err.Error(), "B") {
272					t.Errorf("error %q must name referrer H and deleted upstream B", err)
273				}
274				if report != nil {
275					t.Errorf("rejected %s returned a success report: %+v", mode, report)
276				}
277	
278				// Atomicity: every dataset, every direct-upstream list, and every
279				// derived downstream list must remain as submitted. In particular
280				// C's otherwise-legal repoint to R must not have taken effect.
281				if got := dump(graph); got != before {
282					t.Fatalf("rejected %s mutated the graph:\n got  %s\nwant %s", mode, got, before)
283				}
284				if _, ok := graph["M"]; !ok {
285					t.Errorf("M disappeared on rejected %s", mode)
286				}
287				if _, ok := graph["B"]; !ok {
288					t.Errorf("B disappeared on rejected %s", mode)
289				}
290				if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"M"}) {
291					t.Errorf("C.Parents = %v, want [M] (legal repoint must not apply early)", got)
292				}
293				if got := graph["H"].Parents; !reflect.DeepEqual(got, []string{"B", "C"}) {
294					t.Errorf("H.Parents = %v, want [B C]", got)
295				}
296				if got := graph["M"].Children; !reflect.DeepEqual(got, []string{"B", "C"}) {
297					t.Errorf("M.Children = %v, want [B C]", got)
298				}
299				if got := graph["R"].Children; !reflect.DeepEqual(got, []string{"M"}) {
300					t.Errorf("R.Children = %v, want [M] (R->C must not appear early)", got)
301				}
302				if got := graph["S"].Children; len(got) != 0 {
303					t.Errorf("S.Children = %v, want empty", got)
304				}
305				// The isolated component is completely unaffected as well.
306				if got := graph["V"].Parents; !reflect.DeepEqual(got, []string{"U"}) {
307					t.Errorf("V.Parents = %v, want [U]", got)
308				}
309			})
310		}
311	}
312	
313	// TestBatchDeleteSharedIntermediateDeterministic: reordering graph records,
314	// plan records, removal entries, and upstream names — or repeating one of H's
315	// upstreams — carries no semantics, so the applied graph and the success report
316	// must be byte-identical in every variant.
317	func TestBatchDeleteSharedIntermediateDeterministic(t *testing.T) {
318		canonicalGraph := func() map[string]*Lineage { return convergenceBatchGraph(t) }
319		canonicalPlan := convergenceBatchPlan()
320	
321		variants := []struct {
322			name  string
323			graph func() map[string]*Lineage
324			plan  Plan
325		}{
326			{
327				name:  "canonical",
328				graph: canonicalGraph,
329				plan:  canonicalPlan,
330			},
331			{
332				name: "shuffled graph records",
333				graph: func() map[string]*Lineage {
334					// Same graph, records in a different on-disk order (the file
335					// reader accepts any order and normalizes).
336					graph, err := UnmarshalGraphFile([]byte(`{"datasets":[
337						{"name":"V","upstreams":["U"]},
338						{"name":"T","upstreams":["H"]},
339						{"name":"U","upstreams":[]},
340						{"name":"H","upstreams":["C","B"]},
341						{"name":"C","upstreams":["M"]},
342						{"name":"B","upstreams":["M"]},
343						{"name":"S","upstreams":[]},
344						{"name":"M","upstreams":["R"]},
345						{"name":"R","upstreams":[]}
346					]}`))
347					if err != nil {
348						t.Fatalf("UnmarshalGraphFile unexpected error: %v", err)
349					}
350					return graph
351				},
352				plan: canonicalPlan,
353			},
354			{
355				name:  "shuffled change and removal order",
356				graph: canonicalGraph,
357				plan: Plan{
358					Changes:  []PlanChange{change("H", "S", "C"), change("C", "R")},
359					Removals: []string{"B", "M"},
360				},
361			},
362			{
363				name:  "shuffled and duplicated upstreams",
364				graph: canonicalGraph,
365				plan: Plan{
366					Changes: []PlanChange{
367						change("C", "R", "R"),
368						change("H", "S", "C", "S", "C"),
369					},
370					Removals: []string{"M", "B"},
371				},
372			},
373		}
374	
375		var wantGraph, wantReport []byte
376		for i, tc := range variants {
377			graph := tc.graph()
378			report, err := ApplyBatch(graph, tc.plan)
379			if err != nil {
380				t.Fatalf("%s: ApplyBatch unexpected error: %v", tc.name, err)
381			}
382			gotGraph, err := MarshalGraphFile(graph)
383			if err != nil {
384				t.Fatalf("%s: MarshalGraphFile unexpected error: %v", tc.name, err)
385			}
386			gotReport, err := json.Marshal(report)
387			if err != nil {
388				t.Fatalf("%s: marshal report: %v", tc.name, err)
389			}
390			if i == 0 {
391				wantGraph, wantReport = gotGraph, gotReport
392				continue
393			}
394			if string(gotGraph) != string(wantGraph) {
395				t.Fatalf("%s: graph bytes differ:\n--- got ---\n%s\n--- want ---\n%s", tc.name, gotGraph, wantGraph)
396			}
397			if string(gotReport) != string(wantReport) {
398				t.Fatalf("%s: report bytes differ:\n--- got ---\n%s\n--- want ---\n%s", tc.name, gotReport, wantReport)
399			}
400		}
401	}
402

