32	// captureStdout runs fn with os.Stdout and os.Stderr redirected to pipes,
33	// returning what was written to each.
34	func captureStdout(t *testing.T, fn func() int) (stdout, stderr string, exit int) {
35		t.Helper()
36		oldStdout := os.Stdout
37		oldStderr := os.Stderr
38		rOut, wOut, err := os.Pipe()
39		if err != nil {
40			t.Fatalf("pipe: %v", err)
41		}
42		rErr, wErr, err := os.Pipe()
43		if err != nil {
44			t.Fatalf("pipe: %v", err)
45		}
46		os.Stdout = wOut
47		os.Stderr = wErr
48	
49		exit = fn()
50	
51		wOut.Close()
52		wErr.Close()
53		outBytes, _ := readAll(rOut)
54		errBytes, _ := readAll(rErr)
55		os.Stdout = oldStdout
56		os.Stderr = oldStderr
57		return string(outBytes), string(errBytes), exit
58	}
59	
60	func readAll(f *os.File) ([]byte, error) {
61		var out []byte
62		buf := make([]byte, 4096)
63		for {
64			n, err := f.Read(buf)
65			out = append(out, buf[:n]...)
66			if err != nil {
67				break
68			}
69		}
70		return out, nil
71	}
