129			"replace query name in path": func(r *TraceReport, i int) {
130				r.Sources[i].Path[0] = "HACK"
131			},
132			"replace intermediate name in path": func(r *TraceReport, i int) {
133				r.Sources[i].Path[1] = "HACK"
134			},
